    fun maxSubArray(nums: IntArray): Int {
        if (nums.size == 1) return nums[0]

        var sum = 0
        var maxSum = nums[0]

        for (n in nums) {
            sum += n
            maxSum = max(maxSum, sum)

            if (sum < 0) {
                sum = 0
            }
        }
        return maxSum
    }
}

