    pub fn max_sub_array(nums: Vec<i32>) -> i32 {
        if nums.len() == 1 {
            return nums[0];
        }

        let mut sum = 0;
        let mut max = nums[0];

        for n in nums {
            sum += n;
            max = max.max(sum);

            if sum < 0 {
                sum = 0;
